cy.intercept('GET', `${apiUrl}/posts`, {
  statusCode: 500,
  body: {
    error: 'Internal Server Error'
  }
}).as('getPostsFailure');
fetchInBrowser(`${apiUrl}/posts`).then(({
  status,
  body
}) => {
  expect(status).to.eq(500);
  expect(body).to.have.property('error');
});
cy.wait('@getPostsFailure');

cy.intercept('GET', `${apiUrl}/users`, {
  forceNetworkError: true
}).as('getUsersNetworkError');
cy.window().then(win => win.fetch(`${apiUrl}/users`).then(() => {
  throw new Error('fetch should not have resolved successfully');
}, err => {
  expect(err).to.exist;
}));
cy.wait('@getUsersNetworkError');

cy.intercept('GET', `${apiUrl}/posts/1`, {
  statusCode: 200,
  body: {
    id: 1,
    title: 'Delayed post'
  },
  delay: 1000
}).as('getSlowPost');
fetchInBrowser(`${apiUrl}/posts/1`).then(({
  status,
  body
}) => {
  expect(status).to.eq(200);
  expect(body.title).to.eq('Delayed post');
});
cy.wait('@getSlowPost');

const payload = {
  title: 'Stubbed title',
  body: 'Stubbed body',
  userId: 1
};
cy.intercept('POST', `${apiUrl}/posts`, req => {
  expect(req.body).to.deep.equal(payload);
  req.reply({
    statusCode: 201,
    body: _objectSpread({
      id: 101
    }, req.body)
  });
}).as('createPostStubbed');
fetchInBrowser(`${apiUrl}/posts`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(payload)
}).then(({
  status,
  body
}) => {
  expect(status).to.eq(201);
  expect(body.id).to.eq(101);
  expect(body.title).to.eq(payload.title);
});
cy.wait('@createPostStubbed');
